-- Carga los 500 perfumes del catálogo. Correr UNA vez, DESPUÉS de esquema.sql (SQL Editor de Supabase → Run).
-- Si un perfume ya existe (mismo id) no se toca: así no se pisan precios o existencias ya editados.
begin;
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('perfumes','id'), greatest(1000000, (select max(id) from perfumes)));
commit;
